mapper.select:
select user.id, user.name, `password`, user.tid, did, rid, phone, email,
       `status`,tenant.name as tenant,department.`name` as department,
        role.name as role,user.create_time as createTime,user.update_time as updateTime
from `user`
         join tenant on tenant.id = user.tid
         join department on department.id = user.did
         join role on role.id = user.rid

     and department.name= #{department}
     and status = #{status} 
     and user.id like concat('%', #{id}, '%')  
     and user.name like concat('%', #{name}, '%')  
     and user.role = #{role} 
     and user.tid = #{tid} 
     and user.did = #{did} 

order by create_time desc
